import openpyxl
inp = openpyxl.load_workbook('filled.xlsx', data_only=False)
gold = openpyxl.load_workbook('/mnt/hhq/data/data_pipeline/generated_tasks/route_b_answer_files_batch1/passed/template/2_404-14_answer_template_2981_golden.xlsx', data_only=False)
# Compare all cells: value, data_type, number_format, fill fg, font color, border style summary, alignment
def fg(c):
    try:
        return c.fill.fgColor.rgb if c.fill and c.fill.fgColor else None
    except Exception:
        return 'ERR'
def fontcolor(c):
    try:
        return c.font.color.rgb if c.font and c.font.color else None
    except Exception:
        return 'ERR'
total_diffs = 0
for ws in inp.worksheets:
    gw = gold[ws.title]
    for row in ws.iter_rows(min_row=1, max_row=max(ws.max_row,gw.max_row), max_col=max(ws.max_column,gw.max_column)):
        for c in row:
            gc = gw[c.coordinate]
            diffs=[]
            if c.value != gc.value:
                diffs.append(f'val {c.value!r} vs {gc.value!r}')
            if c.data_type != gc.data_type:
                diffs.append(f'type {c.data_type} vs {gc.data_type}')
            if c.number_format != gc.number_format:
                diffs.append(f'fmt {c.number_format!r} vs {gc.number_format!r}')
            if fg(c) != fg(gc):
                diffs.append(f'fill {fg(c)} vs {fg(gc)}')
            if fontcolor(c) != fontcolor(gc):
                diffs.append(f'fontcol {fontcolor(c)} vs {fontcolor(gc)}')
            # border
            def border_key(b):
                if not b: return None
                return tuple((side, getattr(b,side).style if getattr(b,side) else None, getattr(b,side).color.rgb if getattr(b,side) and getattr(b,side).color else None) for side in ['left','right','top','bottom'])
            if border_key(c.border) != border_key(gc.border):
                diffs.append(f'border {border_key(c.border)} vs {border_key(gc.border)}')
            # alignment
            def align_key(a):
                if not a: return None
                return (a.horizontal, a.vertical, a.wrap_text)
            if align_key(c.alignment) != align_key(gc.alignment):
                diffs.append(f'align {align_key(c.alignment)} vs {align_key(gc.alignment)}')
            if diffs:
                total_diffs += 1
                print(ws.title, c.coordinate, diffs)
print('TOTAL DIFFS', total_diffs)
